ALTER TABLE public.crews ADD COLUMN member_capacity integer NOT NULL DEFAULT 50 CHECK(member_capacity BETWEEN 2 AND 500);
ALTER TABLE public.posts ADD COLUMN lesson_seconds integer;
CREATE OR REPLACE FUNCTION public.can_read_post(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_id AND (p.user_id=auth.uid() OR (NOT p.hidden AND (NOT EXISTS(SELECT 1 FROM public.challenges ch WHERE ch.season_id=p.season_id AND NOT ch.public_board) OR EXISTS(SELECT 1 FROM public.season_entries e WHERE e.season_id=p.season_id AND e.user_id=auth.uid())) AND (p.visibility='everyone' OR EXISTS(SELECT 1 FROM public.crew_members m WHERE m.crew_id=p.crew_id AND m.user_id=auth.uid()))))) $$;
CREATE FUNCTION public.guard_challenge_post() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.challenges WHERE season_id=NEW.season_id AND NOT public_board AND audience<>'solo') THEN NEW.visibility:='crew'; END IF; RETURN NEW; END $$; CREATE TRIGGER private_challenge_post BEFORE INSERT ON public.posts FOR EACH ROW EXECUTE FUNCTION public.guard_challenge_post();
CREATE FUNCTION public.create_boss_lesson(_boss_id uuid,_body text,_seconds integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bosses; pid uuid; BEGIN SELECT * INTO b FROM public.bosses WHERE id=_boss_id; IF auth.uid() IS NULL OR b.metric IS DISTINCT FROM 'posts' OR now() NOT BETWEEN b.starts_at AND b.ends_at OR _seconds NOT BETWEEN 60 AND 3600 OR char_length(trim(_body)) NOT BETWEEN 20 AND 280 THEN RAISE EXCEPTION 'invalid_lesson'; END IF; pid:=public.create_post(b.season_id,'thought',NULL,_body); UPDATE public.posts SET lesson_seconds=_seconds,stats=stats||jsonb_build_object('boss_lesson',true) WHERE id=pid AND user_id=auth.uid(); RETURN pid; END $$;
CREATE FUNCTION public.post_small_wins(_season_id uuid,_wins text[],_language text,_caption text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE body text; faith boolean; valid text[]; labels jsonb:='{"water":{"en":"Drank 2 L water","fr":"Bu 2 L d’eau","ar":"شربت لترين من الماء","aeb":"شربت 2 لتر ماء"},"stairs":{"en":"Took the stairs","fr":"Pris les escaliers","ar":"استخدمت الدرج","aeb":"طلعت في الدروج"},"coffee":{"en":"Coffee, no sugar","fr":"Café sans sucre","ar":"قهوة بلا سكر","aeb":"قهوة بلا سكّر"},"fajr":{"en":"Fajr on time","fr":"Fajr à l’heure","ar":"الفجر في وقته","aeb":"الفجر في وقتو"},"read":{"en":"Read 10 pages","fr":"Lu 10 pages","ar":"قرأت 10 صفحات","aeb":"قريت 10 صفحات"},"dinner":{"en":"Phone-free dinner","fr":"Dîner sans téléphone","ar":"عشاء بلا هاتف","aeb":"عشاء بلا تليفون"},"steps":{"en":"8k steps","fr":"8k pas","ar":"8 آلاف خطوة","aeb":"8 آلاف خطوة"},"sleep":{"en":"In bed by 23:00","fr":"Au lit à 23 h","ar":"في السرير قبل 23:00","aeb":"رقدت قبل 23:00"},"dessert":{"en":"Said no to dessert","fr":"Dit non au dessert","ar":"رفضت الحلوى","aeb":"قلت لا للحلو"}}'; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF; IF cardinality(_wins) NOT BETWEEN 1 AND 9 OR _language NOT IN ('en','fr','ar','aeb') OR char_length(_caption)>80 OR EXISTS(SELECT 1 FROM unnest(_wins) w WHERE NOT labels ? w) THEN RAISE EXCEPTION 'invalid_win'; END IF; SELECT faith_public INTO faith FROM public.profiles WHERE id=auth.uid(); SELECT array_agg(DISTINCT w) INTO valid FROM unnest(_wins) w WHERE w<>'fajr' OR faith; IF coalesce(cardinality(valid),0)=0 THEN RAISE EXCEPTION 'private_faith'; END IF; SELECT string_agg(labels->w->>_language,' · ') INTO body FROM unnest(valid) w; body:=left(body||E'\n“'||coalesce(_caption,'')||'”',280); RETURN public.create_post(_season_id,'win',NULL,body); END $$;
CREATE FUNCTION public.guard_creator_crew() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.kind='creator' AND NOT public.has_role(NEW.owner_id,'creator') THEN RAISE EXCEPTION 'creator_required'; END IF; RETURN NEW; END $$; CREATE TRIGGER creator_crew_guard BEFORE INSERT ON public.crews FOR EACH ROW EXECUTE FUNCTION public.guard_creator_crew();
CREATE FUNCTION public.guard_shared_habit_delete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.challenges WHERE season_id=OLD.season_id AND same_habits) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=OLD.user_id) THEN RAISE EXCEPTION 'challenge_habits_locked'; END IF; RETURN OLD; END $$; CREATE TRIGGER shared_habit_delete_guard BEFORE DELETE ON public.user_habits FOR EACH ROW EXECUTE FUNCTION public.guard_shared_habit_delete();
REVOKE ALL ON FUNCTION public.create_boss_lesson(uuid,text,integer),public.post_small_wins(uuid,text[],text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_boss_lesson(uuid,text,integer),public.post_small_wins(uuid,text[],text,text) TO authenticated;
CREATE FUNCTION public.guard_active_challenge() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.active_challenge_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.challenges c JOIN public.season_entries e ON e.season_id=c.season_id WHERE c.id=NEW.active_challenge_id AND e.user_id=NEW.user_id) THEN RAISE EXCEPTION 'forbidden'; END IF; RETURN NEW; END $$; CREATE TRIGGER active_challenge_guard BEFORE INSERT OR UPDATE ON public.user_preferences FOR EACH ROW EXECUTE FUNCTION public.guard_active_challenge();